/** @jsxImportSource preact */
import { useEffect, useRef } from "preact/hooks";
import { mountFeatureVoteBoard, type FeatureVoteBoardOptions } from "../../components/feature-vote-board/FeatureVoteBoardEngine.js";
import type { MotionController } from "../../components/feature-vote-board/motion-runtime";

export function FeatureVoteBoard({ options, className }: { options?: FeatureVoteBoardOptions; className?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<MotionController | null>(null);
  useEffect(() => {
    const instance = mountFeatureVoteBoard(host.current!, options);
    controller.current = instance;
    return () => { instance.destroy(); controller.current = null; };
    // Options are updated below without remounting the state machine.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { controller.current?.update(options ?? {}); }, [options]);
  return <div ref={host} className={className} data-motion-component="feature-vote-board" />;
}

